-- Run AFTER DEPLOY-ASSESSMENT-SCHEMA-2026-09-11.sql in the test Supabase SQL editor.
-- Imports the reviewed local bank as a DRAFT for admin review and publication.
-- Refuses to overwrite any existing assessment draft or published bank.
-- Contains assessment scoring criteria; do not place this file under public/.
begin;
lock table public.content_documents in share row exclusive mode;
do $import$
begin
  if exists (select 1 from public.content_documents where kind = 'assessment_arc') then
    raise exception 'An assessment bank already exists. No changes made. Review it in Admin before importing.';
  end if;
  insert into public.content_documents (kind, version, status, data, note)
  values ('assessment_arc', 1, 'draft', $assessment_bank${
